namespace ToneCustoms.ShellStudio.Export;
public sealed class FiveMInstallService { public string Install(string builtResource,string resourcesRoot){if(!Directory.Exists(builtResource))throw new DirectoryNotFoundException(builtResource);Directory.CreateDirectory(resourcesRoot);var dest=Path.Combine(resourcesRoot,Path.GetFileName(builtResource));if(Directory.Exists(dest))Directory.Delete(dest,true);Copy(builtResource,dest);return dest;}static void Copy(string src,string dst){Directory.CreateDirectory(dst);foreach(var f in Directory.GetFiles(src))File.Copy(f,Path.Combine(dst,Path.GetFileName(f)),true);foreach(var d in Directory.GetDirectories(src))Copy(d,Path.Combine(dst,Path.GetFileName(d)));} }
